def solve(coins, amount):
    # Filter out non-positive coin values to avoid infinite loops
    coins = [c for c in set(coins) if c > 0]
    if amount < 0:
        return -1
    if amount == 0:
        return 0
    if not coins:
        return -1
    # Use DP for unbounded knapsack (coin change)
    # dp[x] = minimal coins to make amount x, initialize to a large sentinel
    max_val = amount + 1  # sentinel greater than any possible solution
    dp = [max_val] * (amount + 1)
    dp[0] = 0
    for a in range(1, amount + 1):
        best = max_val
        for c in coins:
            if c <= a:
                # candidate using coin c
                cand = dp[a - c] + 1
                if cand < best:
                    best = cand
        dp[a] = best
    return dp[amount] if dp[amount] != max_val else -1

