def solve(s):
    n = len(s)
    if n == 0:
        return ''
    start, max_len = 0, 1
    for i in range(n):
        # odd length palindrome
        l, r = i, i
        while l >= 0 and r < n and s[l] == s[r]:
            cur_len = r - l + 1
            if cur_len > max_len:
                start, max_len = l, cur_len
