def solve(s):
    n = len(s)
    if n == 0:
        return ''
    start, max_len = 0, 1
    for i in range(n):
        # odd length palindrome centered at i
        l, r = i, i
        while l >= 0 and r < n and s[l] == s[r]:
            cur_len = r - l + 1
            if cur_len > max_len:
                start, max_len = l, cur_len
            l -= 1
            r += 1
        # even length palindrome centered between i and i+1
        l, r = i, i + 1
        while l >= 0 and r < n and s[l] == s[r]:
            cur_len = r - l + 1
            if cur_len > max_len:
                start, max_len = l, cur_len
            l -= 1
            r += 1
    return s[start:start+max_len]

