def solve(path):
    """Simplify an absolute Unix-style path.
    - Collapse multiple '/' characters.
    - Resolve '.' (current directory) and '..' (parent directory).
    - Ensure the result starts with '/' and does not end with a trailing slash
      unless it is the root.
    """
    parts = path.split('/')
    stack = []
    for part in parts:
        if part == '' or part == '.':
            # empty part due to // or current directory – ignore
            continue
        if part == '..':
            # go up one directory if possible
            if stack:
                stack.pop()
        else:
            stack.append(part)
    # Reconstruct the normalized path
    return '/' + '/'.join(stack)

