    """Return the k most frequent distinct words, breaking ties alphabetically.
    If k is not a positive integer, return an empty list.
    """
    # Validate k
    if not isinstance(k, int) or k <= 0:
        return []
    # Count frequencies safely; if words contain unhashable items, fall back to manual count
    try:
        from collections import Counter
        freq = Counter(words)
    except TypeError:
        freq = {}
        for w in words:
            try:
                freq[w] = freq.get(w, 0) + 1
