def solve(words, k):
    """Return the k most frequent distinct words, breaking ties alphabetically.
    If k is not a positive integer, return an empty list.
    """
    # Validate k
    if not isinstance(k, int) or k <= 0:
        return []
    # Count frequencies safely; if words contain unhashable items, fall back to manual count
    try:
        from collections import Counter
        freq = Counter(words)
    except TypeError:
        freq = {}
        for w in words:
            try:
                freq[w] = freq.get(w, 0) + 1
            except Exception:
                # Skip unhashable items
                continue
    # Sort by descending frequency then alphabetically (lexicographically)
    sorted_items = sorted(freq.items(), key=lambda x: (-x[1], x[0]))
    # Return up to k words (distinct)
    return [word for word, _ in sorted_items[:k]]
}

