def solve(s: str) -> int:
    """Return length of the longest substring without repeating characters.
    Uses sliding window with a dict storing last index of each character.
    """
    last_index = {}
    start = 0
    max_len = 0
    for i, ch in enumerate(s):
        if ch in last_index and last_index[ch] >= start:
            # repeated character within current window, move start
            start = last_index[ch] + 1
        last_index[ch] = i
        cur_len = i - start + 1
        if cur_len > max_len:
            max_len = cur_len
    return max_len

