def solve(coins, amount):
    """Return the minimum number of coins needed to make up *amount* using unlimited
    supply of the given positive *coins*. Return -1 if impossible.
    This implementation uses a DP that iterates over coins first, which is faster
    for large *amount* values.
    """
    if amount < 0:
        return -1
    if amount == 0:
        return 0
    # Keep only positive coin values
    coins = [c for c in coins if c > 0]
    if not coins:
        return -1
    INF = amount + 1
    dp = [INF] * (amount + 1)
    dp[0] = 0
    for c in coins:
        for a in range(c, amount + 1):
            # If dp[a - c] is reachable, update dp[a]
            if dp[a - c] + 1 < dp[a]:
                dp[a] = dp[a - c] + 1
    return dp[amount] if dp[amount] != INF else -1

