    n = max(len(row) for row in grid) if m else 0
    visited = [[False]*n for _ in range(m)]
    def dfs(i, j):
        stack = [(i, j)]
        while stack:
            x, y = stack.pop()
            if x < 0 or x >= m or y < 0 or y >= len(grid[x]):
                continue
            if visited[x][y]:
                continue
            if not grid[x][y]:
                continue
            visited[x][y] = True
            for dx, dy in ((1,0),(-1,0),(0,1),(0,-1)):
                nx, ny = x+dx, y+dy
                stack.append((nx, ny))
    count = 0
    for i in range(m):
        for j in range(len(grid[i])):
            if grid[i][j] and not visited[i][j]:
                dfs(i, j)
                count += 1
    return count

