    Uses sliding window with a dictionary storing the last index of each character.
    """
    last_seen = {}
    start = 0
    max_len = 0
    for i, ch in enumerate(s):
        if ch in last_seen and last_seen[ch] >= start:
            start = last_seen[ch] + 1
        last_seen[ch] = i
        curr_len = i - start + 1
        if curr_len > max_len:
            max_len = curr_len
    return max_len

