    """Simplify an absolute Unix file path.

    The path is absolute (starts with '/'). Resolve '.' (current dir) and '..'
    (parent dir), collapse multiple slashes, and ensure the result has no
    trailing slash unless it is the root.
    """
    parts = path.split('/')
    stack = []
    for part in parts:
        if not part or part == '.':
            continue
        if part == '..':
            if stack:
                stack.pop()
        else:
            stack.append(part)
    return '/' + '/'.join(stack)
