def solve(n, edges):
    from heapq import heappush, heappop
    # Build adjacency list and indegree counts
    adj = [[] for _ in range(n)]
    indeg = [0] * n
    for a, b in edges:
        if 0 <= a < n and 0 <= b < n:
            adj[a].append(b)
            indeg[b] += 1
    # Use min-heap to always pick smallest available node
    heap = []
    for i in range(n):
        if indeg[i] == 0:
            heappush(heap, i)
    order = []
    while heap:
        u = heappop(heap)
        order.append(u)
        for v in adj[u]:
            indeg[v] -= 1
            if indeg[v] == 0:
                heappush(heap, v)
    if len(order) != n:
        return []
    return order

