def solve(matrix):
    """Return the determinant of a square integer matrix.
    An empty matrix (no rows) has determinant 1.
    Uses exact rational Gaussian elimination.
    """
    n = len(matrix)
    if n == 0:
        return 1
    # Verify square; if not, treat as 0 determinant
    for row in matrix:
        if len(row) != n:
            return 0
    # Convert to Fraction matrix
    A = [[Fraction(val) for val in row] for row in matrix]
