from fractions import Fraction

def solve(matrix):
    """Return the determinant of a square integer matrix.
    An empty matrix (no rows) has determinant 1.
    Uses exact rational Gaussian elimination.
    """
    n = len(matrix)
    if n == 0:
        return 1
    # Verify square; if not, treat as 0 determinant
    for row in matrix:
        if len(row) != n:
            return 0
    # Convert to Fraction matrix
    A = [[Fraction(val) for val in row] for row in matrix]
    det = Fraction(1)
    for i in range(n):
        # Find pivot
        pivot_row = None
        for r in range(i, n):
            if A[r][i] != 0:
                pivot_row = r
                break
        if pivot_row is None:
            return 0
        if pivot_row != i:
            A[i], A[pivot_row] = A[pivot_row], A[i]
            det = -det
        pivot = A[i][i]
        det *= pivot
        # Normalize rows below
        for r in range(i + 1, n):
            factor = A[r][i] / pivot
            if factor == 0:
                continue
            for c in range(i, n):
                A[r][c] -= factor * A[i][c]
    # det is product of pivots (already multiplied)
    # Convert to int (determinant of integer matrix is integer)
    return int(det)

