    tails = []  # tails[i] = smallest possible tail of an increasing subseq of length i+1
    for x in nums:
        # find leftmost position to replace (first >= x)
        i = bisect.bisect_left(tails, x)
        if i == len(tails):
            tails.append(x)
        else:
            tails[i] = x
    return len(tails)

