    """Return the length of the longest strictly increasing subsequence.
    Uses patience sorting with O(n log n) time.
    """
    import bisect
    if not nums:
        return 0
    tails = []  # tails[i] = smallest possible tail of an inc subseq of length i+1
    for x in nums:
        # find location to replace: first element >= x
        idx = bisect.bisect_left(tails, x)
        if idx == len(tails):
            tails.append(x)
        else:
            tails[idx] = x
    return len(tails)

